function eliminarDuplicados(array) {
  return [...new Set(array)];
}

const numeros = [1, 2, 3, 2, 1, 4, 3];
const palabras = ['hola', 'mundo', 'hola', 'js'];

const r1 = eliminarDuplicados(numeros);
const r2 = eliminarDuplicados(palabras);
const r1Length = r1.length;
const r2Length = r2.length;

console.log(r1, r1Length);
console.log(r2, r2Length);

function union(a, b) {
  return [...new Set([...a, ...b])];
}

function interseccion(a, b) {
  const setB = new Set(b);
  return [...new Set(a)].filter(x => setB.has(x));
}

function diferencia(a, b) {
  const setB = new Set(b);
  return [...new Set(a)].filter(x => !setB.has(x));
}

const setA = [1, 2, 3, 4];
const setB = [3, 4, 5, 6];

const u = union(setA, setB);
const i = interseccion(setA, setB);
const d = diferencia(setA, setB);

console.log('Unión:', u);
console.log('Intersección:', i);
console.log('Diferencia:', d);

function analizarTexto(texto) {
  const palabras = texto.toLowerCase().split(' ');

  // Palabras únicas
  const setPalabras = new Set(palabras);

  // Caracteres únicos (sin espacios)
  const setCaracteres = new Set(texto.toLowerCase().replace(/ /g, '').split(''));

  // Frecuencia de palabras
  const frecuencia = new Map();
  for (const palabra of palabras) {
    frecuencia.set(palabra, (frecuencia.get(palabra) ?? 0) + 1);
  }

  // Palabra más frecuente
  let masFrecuente = '';
  let maxCount = 0;
  for (const [palabra, count] of frecuencia) {
    if (count > maxCount) {
      maxCount = count;
      masFrecuente = palabra;
    }
  }

  return {
    palabrasUnicas: setPalabras.size,
    caracteresUnicos: setCaracteres.size,
    frecuenciaPalabras: frecuencia,
    palabraMasFrecuente: masFrecuente,
  };
}

const resultado = analizarTexto('el sol sale y el sol brilla y el sol ilumina');

console.log('Palabras únicas:', resultado.palabrasUnicas);
console.log('Caracteres únicos:', resultado.caracteresUnicos);
console.log('Más frecuente:', resultado.palabraMasFrecuente);
console.log('Frecuencia de "el":', resultado.frecuenciaPalabras.get('el'));
